BEGIN;

CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "pg_graphql";
CREATE EXTENSION IF NOT EXISTS "pg_stat_statements";

CREATE TABLE IF NOT EXISTS public."activity_logs" (
    "id" uuid DEFAULT gen_random_uuid(),
    "user_id" uuid,
    "user_name" character varying(255) DEFAULT 'System'::character varying,
    "action" character varying(50),
    "entity_type" character varying(50),
    "entity_id" uuid,
    "description" text,
    "old_data" jsonb,
    "new_data" jsonb,
    "ip_address" character varying(45),
    "user_agent" text,
    "created_at" timestamp with time zone DEFAULT now(),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."finances" (
    "id" uuid DEFAULT gen_random_uuid(),
    "date" timestamp with time zone,
    "type" character varying(20),
    "amount" numeric,
    "description" text,
    "payment_id" uuid,
    "created_at" timestamp with time zone DEFAULT now(),
    "updated_at" timestamp with time zone DEFAULT now(),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."payments" (
    "id" uuid DEFAULT gen_random_uuid(),
    "student_id" uuid,
    "month" integer,
    "year" integer,
    "amount" numeric DEFAULT 0,
    "is_paid" boolean DEFAULT false,
    "paid_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT now(),
    "updated_at" timestamp with time zone DEFAULT now(),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."profiles" (
    "id" uuid,
    "role" text DEFAULT 'view'::text,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."settings" (
    "id" uuid DEFAULT gen_random_uuid(),
    "key" character varying(100),
    "value" text,
    "description" character varying(255),
    "updated_at" timestamp with time zone DEFAULT now(),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."students" (
    "id" uuid DEFAULT gen_random_uuid(),
    "name" character varying(255),
    "class" character varying(20),
    "year_enrolled" integer,
    "status" character varying(20) DEFAULT 'active'::character varying,
    "created_at" timestamp with time zone DEFAULT now(),
    "updated_at" timestamp with time zone DEFAULT now(),
    "has_tabungan" boolean DEFAULT false,
    "inactive_reason" character varying(50),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."tabungan" (
    "id" uuid DEFAULT gen_random_uuid(),
    "student_id" uuid,
    "saldo" numeric DEFAULT 0,
    "jumlah_transaksi" integer DEFAULT 0,
    "updated_at" timestamp with time zone DEFAULT now(),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."tabungan_transaksi" (
    "id" uuid DEFAULT gen_random_uuid(),
    "student_id" uuid,
    "tanggal" timestamp with time zone DEFAULT now(),
    "jenis" character varying(10),
    "nominal" numeric,
    "keterangan" text,
    "saldo_setelah" numeric,
    "created_at" timestamp with time zone DEFAULT now(),
    PRIMARY KEY ("id")
);

ALTER TABLE public."activity_logs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."finances" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."payments" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."profiles" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."settings" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."students" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."tabungan" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."tabungan_transaksi" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow all for authenticated users" ON public."finances" FOR ALL TO authenticated
  USING (true)
  WITH CHECK (true)
;

CREATE POLICY "Allow read for view and edit" ON public."payments" FOR SELECT TO authenticated
  USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['view'::text, 'edit'::text]))))))
;

CREATE POLICY "Allow write for edit" ON public."payments" FOR ALL TO authenticated
  USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'edit'::text)))))
  WITH CHECK ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'edit'::text)))))
;

CREATE POLICY "Enable select for all users" ON public."payments" FOR SELECT TO authenticated
  USING (true)
;

