ALTER TABLE public."payments" ADD CONSTRAINT fk_payments_student_id FOREIGN KEY ("student_id") REFERENCES public."students"("id") ON DELETE CASCADE
;

ALTER TABLE public."tabungan" ADD CONSTRAINT fk_tabungan_student_id FOREIGN KEY ("student_id") REFERENCES public."students"("id") ON DELETE CASCADE
;

