;

CREATE INDEX idx_students_name ON public.students USING btree (name);

CREATE INDEX idx_students_class ON public.students USING btree (class);

CREATE INDEX idx_students_status ON public.students USING btree (status);

CREATE INDEX idx_students_year ON public.students USING btree (year_enrolled);

CREATE UNIQUE INDEX payments_student_id_month_year_key ON public.payments USING btree (student_id, month, year);

CREATE INDEX idx_payments_student ON public.payments USING btree (student_id);

CREATE INDEX idx_payments_period ON public.payments USING btree (year, month);

CREATE INDEX idx_payments_status ON public.payments USING btree (is_paid);

CREATE INDEX idx_logs_action ON public.activity_logs USING btree (action);

CREATE INDEX idx_logs_entity ON public.activity_logs USING btree (entity_type, entity_id);

CREATE INDEX idx_logs_user ON public.activity_logs USING btree (user_id);

CREATE INDEX idx_logs_date ON public.activity_logs USING btree (created_at DESC);

CREATE INDEX idx_logs_description ON public.activity_logs USING gin (to_tsvector('indonesian'::regconfig, description));

CREATE UNIQUE INDEX settings_key_key ON public.settings USING btree (key);

CREATE INDEX idx_finances_date ON public.finances USING btree (date);

CREATE INDEX idx_finances_type ON public.finances USING btree (type);

CREATE INDEX idx_finances_payment_id ON public.finances USING btree (payment_id);

CREATE UNIQUE INDEX tabungan_student_id_key ON public.tabungan USING btree (student_id);

CREATE INDEX idx_tabungan_student_id ON public.tabungan USING btree (student_id);

CREATE INDEX idx_tabungan_transaksi_student_id ON public.tabungan_transaksi USING btree (student_id);

CREATE INDEX idx_tabungan_transaksi_tanggal ON public.tabungan_transaksi USING btree (tanggal);

CREATE OR REPLACE FUNCTION public.insert_tabungan_on_has_tabungan_true()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.has_tabungan = true AND (SELECT COUNT(*) FROM tabungan WHERE student_id = NEW.id) = 0 THEN

    VALUES (NEW.id, 0, 0, NOW());
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_has_tabungan_false()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE public.students
  SET has_tabungan = false
  WHERE id = OLD.student_id;
  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_has_tabungan_true()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE public.students
  SET has_tabungan = true
  WHERE id = NEW.student_id;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_payment_to_finances()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  student_name TEXT;
  month_name TEXT;
  month_names TEXT[] := ARRAY['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
BEGIN
  -- Get student name
  SELECT name INTO student_name FROM public.students WHERE id = NEW.student_id;
  
  -- Get month name
  month_name := month_names[NEW.month];

  -- When payment becomes PAID (INSERT or UPDATE to is_paid = true)
  IF NEW.is_paid = true AND (OLD IS NULL OR OLD.is_paid = false) THEN

    VALUES (
      COALESCE(NEW.paid_at, NOW()),
      'income',
      NEW.amount,
      student_name || ' membayar iuran bulan ' || month_name || ' ' || NEW.year,
      NEW.id
    );
  END IF;
  
  -- When payment becomes UNPAID (is_paid changes to false)
  IF NEW.is_paid = false AND OLD IS NOT NULL AND OLD.is_paid = true THEN
    DELETE FROM public.finances WHERE payment_id = OLD.id;
  END IF;
  
  RETURN NEW;
END;
$function$


CREATE TRIGGER trg_set_has_tabungan_true AFTER INSERT ON public.tabungan FOR EACH ROW EXECUTE FUNCTION set_has_tabungan_true();

CREATE TRIGGER trg_set_has_tabungan_false AFTER DELETE ON public.tabungan FOR EACH ROW EXECUTE FUNCTION set_has_tabungan_false();

CREATE TRIGGER trg_insert_tabungan_on_has_tabungan_true AFTER UPDATE OF has_tabungan ON public.students FOR EACH ROW WHEN ((new.has_tabungan = true)) EXECUTE FUNCTION insert_tabungan_on_has_tabungan_true();

CREATE TRIGGER payment_finance_sync AFTER INSERT OR UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION sync_payment_to_finances();

ALTER PUBLICATION supabase_realtime ADD TABLE public.students, public.payments, public.settings, public.tabungan, public.tabungan_transaksi, public.finances;


